<?php require __DIR__.'/includes/auth.php';require __DIR__.'/config/database.php';$pageTitle='Publicações';$rows=db()->query("SELECT e.* FROM capitulos e WHERE e.status IN ('Pronto','Agendado','Publicado') ORDER BY COALESCE(e.data_publicacao,'2999-12-31'),e.numero")->fetchAll();require __DIR__.'/includes/header.php';?>
<div class="panel-card"><h2 class="h5 mb-3">Fila editorial</h2><?php if(!$rows): ?><div class="empty-state"><i class="bi bi-calendar2-week fs-1"></i><p class="mt-2">Nenhum capítulo pronto, agendado ou publicado ainda.</p></div><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Capítulo</th><th>Status</th><th>Publicação</th><th>Link</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td>#<?= $r['numero'] ?> — <?= htmlspecialchars($r['titulo']) ?></td><td><?= htmlspecialchars($r['status']) ?></td><td><?= $r['data_publicacao']?date('d/m/Y H:i',strtotime($r['data_publicacao'])):'—' ?></td><td><?= $r['youtube_url']?'<a target="_blank" href="'.htmlspecialchars($r['youtube_url']).'">Abrir</a>':'—' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<?php require __DIR__.'/includes/footer.php';?>